    return (
        <Dialog aria-labelledby="attachment-choice-title" onClose={cancel} open={snapshot !== null}>
            <DialogTitle id="attachment-choice-title">
                Attach {snapshot?.fileCount ?? 0} file{snapshot?.fileCount === 1 ? '' : 's'}
            </DialogTitle>
            <DialogContent>
                <Stack spacing={1.5}>
                    <Typography color="text.secondary">
                        Copy into project saves a copy next to the card, so it stays with the project.
                        Link without copying keeps each file where it is and links to it using its full path.
                    </Typography>
                    {!snapshot?.originalLocationAvailable ? (
                        <Typography color="text.secondary" role="status" variant="caption">
                            Linking without copying is unavailable because this browser cannot access the files&apos; full paths.
                        </Typography>
                    ) : null}
                </Stack>
            </DialogContent>
            <DialogActions sx={{ bgcolor: 'background.default', borderTop: 1, borderColor: 'divider' }}>
                <Button onClick={cancel} variant="outlined">Cancel</Button>
                <Button disabled={!snapshot?.originalLocationAvailable} onClick={useOriginal} variant="outlined">
                    Link without copying
                </Button>
                <Button onClick={copy} variant="contained">Copy into project</Button>
            </DialogActions>
        </Dialog>
    )
}

import { copyAndApplyAttachments } from '../data/card_attachment_operations'
import { projectSessionService } from '../project/project_session_service'
import { attachmentChoiceService } from './attachment_choice_service'
import { attachmentMarkdown, type AttachmentMarkdownInserter } from './attachment_workflow'

/** Runs Markdown attachment choice with new-card draft ownership. */
export async function attachFilesToNewCardMarkdown(files: File[], insertMarkdown: AttachmentMarkdownInserter) {
    const selection = await attachmentChoiceService.choose(files)
    if (!selection) return

    if (selection.choice === 'original') {
        if (!selection.originalPaths) throw new Error('Original attachment paths are unavailable')
        insertMarkdown(attachmentMarkdown(files, selection.originalPaths, true))
        return
    }

    await copyAndApplyAttachments(
        files,
        (selectedFiles) => projectSessionService.copyNewCardAttachments(selectedFiles),
        (attachments) => insertMarkdown(attachmentMarkdown(
            files,
            attachments.map(({ fileName }) => fileName),
            false,
        )),
        (paths) => projectSessionService.deleteNewCardDraftAttachments(paths),
    )
}

